"""Tests for reports.export.export_csv."""

import unittest

from reports.export import export_csv


class ExportCsvTests(unittest.TestCase):
    def test_basic(self):
        rows = [{"a": 1, "b": 2}, {"a": 3, "b": 4}]
        self.assertEqual(export_csv(rows, ["a", "b"]), "a,b\r\n1,2\r\n3,4\r\n")

    def test_header_only_when_no_rows(self):
        self.assertEqual(export_csv([], ["x", "y"]), "x,y\r\n")

    def test_empty_columns(self):
        self.assertEqual(export_csv([{"a": 1}, {}], []), "\r\n\r\n")

    def test_quoting_and_doubling(self):
        rows = [{"a": 'he said "hi"', "b": "x,y"}]
        self.assertEqual(
            export_csv(rows, ["a", "b"]),
            'a,b\r\n"he said ""hi""","x,y"\r\n',
        )

    def test_embedded_newlines_preserved(self):
        rows = [{"a": "line1\nline2\r\nline3"}]
        self.assertEqual(
            export_csv(rows, ["a"]),
            'a\r\n"line1\nline2\r\nline3"\r\n',
        )

    def test_unicode_preserved(self):
        rows = [{"a": "caf\u00e9 \u4e2d\u6587"}]
        self.assertEqual(export_csv(rows, ["a"]), "a\r\ncaf\u00e9 \u4e2d\u6587\r\n")

    def test_missing_and_none_are_empty(self):
        rows = [{"a": None}]
        self.assertEqual(export_csv(rows, ["a", "b"]), "a,b\r\n,\r\n")

    def test_values_str_coerced(self):
        rows = [{"a": 1.5, "b": True}]
        self.assertEqual(export_csv(rows, ["a", "b"]), "a,b\r\n1.5,True\r\n")

    def test_unselected_fields_ignored(self):
        rows = [{"a": 1, "b": 2, "c": 3}]
        self.assertEqual(export_csv(rows, ["c", "a"]), "c,a\r\n3,1\r\n")

    def test_one_shot_generator_inputs(self):
        rows = ({"a": i} for i in range(3))
        cols = (c for c in ["a"])
        self.assertEqual(export_csv(rows, cols), "a\r\n0\r\n1\r\n2\r\n")

    def test_duplicate_columns_rejected(self):
        with self.assertRaises(ValueError):
            export_csv([], ["a", "a"])

    def test_non_string_columns_rejected(self):
        for bad in (1, None, b"a"):
            with self.assertRaises(ValueError):
                export_csv([], [bad])

    def test_inputs_not_mutated(self):
        rows = [{"a": 1}]
        cols = ["a"]
        export_csv(rows, cols)
        self.assertEqual(rows, [{"a": 1}])
        self.assertEqual(cols, ["a"])


if __name__ == "__main__":
    unittest.main()

