def export_csv(rows, columns):
    """Export mappings in column order as RFC 4180 CSV, including the header.

    rows: iterable of mappings.
    columns: ordered iterable of unique string column names.

    Returns a str with the header then one record per row, each record ending
    with CRLF. String values use minimal quoting with quote doubling, and
    embedded CR/LF and Unicode are preserved. Missing fields and None become
    empty strings; other values become str(value). Unselected fields are
    ignored. Inputs are not mutated, and one-shot iterators are supported.

    Raises ValueError for duplicate or non-string column names.
    """
    # Materialize columns first so one-shot iterators are supported and
    # validation happens before any rows are consumed.
    cols = list(columns)
    seen = set()
    for col in cols:
        if not isinstance(col, str):
            raise ValueError("column names must be strings: %r" % (col,))
        if col in seen:
            raise ValueError("duplicate column name: %r" % (col,))
        seen.add(col)

    # With no columns every record has zero fields. Emit one empty record
    # per row; if there are no rows at all, emit a single (header) record.
    if not cols:
        count = 0
        for _ in rows:
            count += 1
        return "\r\n" * (count if count > 0 else 1)

    def _cell(value):
        if value is None:
            return ""
        if isinstance(value, str):
            if any(ch in value for ch in (",", '"', "\r", "\n")):
                return '"' + value.replace('"', '""') + '"'
            return value
        return str(value)

    parts = [",".join(_cell(c) for c in cols) + "\r\n"]
    for row in rows:
        parts.append(",".join(_cell(row.get(c, "")) for c in cols) + "\r\n")
    return "".join(parts)
"}
